import sys
import math
from collections import defaultdict

def prime_factors(n):
    i = 2
    factors = defaultdict(int)
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors[i] += 1
    if n > 1:
        factors[n] += 1
    return factors

def merge_factors(factors_list):
    merged = defaultdict(int)
    for factors in factors_list:
        for prime, count in factors.items():
            merged[prime] = max(merged[prime], count)
    return merged

def count_vertices(factors):
    return sum(factors.values())

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:]))

    factors_list = [prime_factors(ai) for ai in a]
    merged_factors = merge_factors(factors_list)
    total_vertices = count_vertices(merged_factors) + n - 1

    print(total_vertices)

main()
